import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import org.springframework.stereotype.Service;

/**
 * Keeps the messages sent since the application started, so every visit to the contact view
 * shows them. Nothing is written to disk.
 */
@Service
public class ContactMessageService {

    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();

    public void save(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return all sent messages, newest first
     */
    public List<ContactMessage> findAll() {
        return List.copyOf(messages);
    }

    public void clear() {
        messages.clear();
    }
}
