@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Autowired
    private ContactMessageService messages;

    @BeforeEach
    void clearMessages() {
        messages.clear();
    }

    @AfterEach
    void clearMessagesAfterTest() {
        messages.clear();
    }

    @Test
    void showsHeadingAboutLinkAndEmptyEnabledForm() {
        navigate(ContactView.class);

        assertThat($(H1.class).single().getText()).isEqualTo("Contact");
        assertThat($(RouterLink.class).withText("About").exists()).isTrue();
        assertThat(nameField().getValue()).isEmpty();
        assertThat(emailField().getValue()).isEmpty();
        assertThat(phoneField().getValue()).isEmpty();
        assertThat(messageField().getValue()).isEmpty();
        assertThat(sendButton().isEnabled()).isTrue();
        assertThat(grid().getItems()).isEmpty();
    }

    @Test
    void aboutLinkNavigatesToAboutView() {
        navigate(ContactView.class);

        test($(RouterLink.class).withText("About").single()).click();

        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
        assertThat($(H1.class).single().getText()).isEqualTo("About");
    }

    @Test
    void emptyFormReportsEveryMissingRequiredField() {
        navigate(ContactView.class);

        submit();

        assertThat(nameField().isInvalid()).isTrue();
        assertThat(nameField().getErrorMessage()).isEqualTo("Name is required");
        assertThat(emailField().isInvalid()).isTrue();
        assertThat(emailField().getErrorMessage()).isEqualTo("Give an e-mail address or a phone number");
        assertThat(phoneField().isInvalid()).isFalse();
        assertThat(messageField().isInvalid()).isTrue();
        assertThat(messageField().getErrorMessage()).isEqualTo("Message is required");
        assertNothingSent();
    }

    @Test
    void blankNameAndMessageAreRequired() {
        navigate(ContactView.class);
        fill("   ", "", "+358 40 123 4567", "  ");

        submit();

        assertThat(nameField().getErrorMessage()).isEqualTo("Name is required");
        assertThat(messageField().getErrorMessage()).isEqualTo("Message is required");
        assertThat(emailField().isInvalid()).isFalse();
        assertNothingSent();
    }

    @Test
    void malformedEmailIsRejectedEvenWhenPhoneIsGiven() {
        navigate(ContactView.class);
        fill("Ann", "not-an-address", "+358 40 123 4567", "Hello");

