index 0000000..f23f3e7
--- /dev/null
+++ b/src/main/java/com/example/contact/ContactView.java
@@ -0,0 +1,209 @@
+package com.example.contact;
+
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_ADDRESS = Pattern.compile(
+            "[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}");
+
+    private final ContactMessageService messages;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        var aboutLink = new RouterLink("About", AboutView.class);
+
+        configureInputs();
+        configureGrid();
+        configureSendButton();
+        configureLeaveDialog();
+        configureEnterKey(aboutLink);
+
+        var form = new FormLayout(nameField, emailField, phoneField, messageField);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 2));
+        form.setColspan(messageField, 2);
+
+        add(new H1("Contact"), aboutLink, form, sendButton, grid, leaveDialog);
+        grid.setItems(messages.findAll());
+    }
+
+    private void configureInputs() {
+        // EAGER keeps the server's copy of the values current, so the Send button is re-enabled
+        // on the first keystroke and leaving the view sees what is typed.
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        nameField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(e -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(e -> sendButton.setEnabled(true));
+    }
+
+    private void configureGrid() {
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setWidthFull();
+        grid.setAllRowsVisible(true);
+    }
+
+    private void configureSendButton() {
+        sendButton.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        sendButton.addClickListener(e -> sendMessage());
+    }
+
+    private void configureLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add("Leaving now throws away what you typed in the form.");
+
+        var keepEditing = new Button("Keep editing", e -> leaveDialog.close());
+        var discard = new Button("Discard", e -> discardAndLeave());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+    }
+
+    private void configureEnterKey(RouterLink aboutLink) {
+        // Enter in a form control sends. Each shortcut listens on its own control, so a match stops
+        // the key event there: the page-level shortcut below does not send a second time, and the
+        // control's newline or button click is suppressed. Shift+Enter is not matched.
+        for (Component control : List.of(nameField, emailField, phoneField, messageField, sendButton)) {
+            Shortcuts.addShortcutListener(control, this::sendMessage, Key.ENTER).listenOn(control);
+        }
+
+        // Enter with no control focused also sends.
+        Shortcuts.addShortcutListener(UI.getCurrent(), this::sendMessage, Key.ENTER)
+                .allowBrowserDefault()
+                .bindLifecycleTo(this);
+
+        // The link and the grid keep their own Enter instead of sending the form.
+        Shortcuts.addShortcutListener(aboutLink, () -> { }, Key.ENTER)
+                .listenOn(aboutLink)
+                .allowBrowserDefault();
+        Shortcuts.addShortcutListener(grid, () -> { }, Key.ENTER)
+                .listenOn(grid)
+                .allowBrowserDefault();
+    }
+
+    private void sendMessage() {
+        // Enter can arrive when Send is disabled (right after a send) or while the leave dialog is
+        // open, and neither should send or validate.
+        if (!sendButton.isEnabled() || leaveDialog.isOpened() || !validate()) {
+            return;
+        }
+
+        messages.save(new ContactMessage(
+                nameField.getValue().trim(),
+                emailField.getValue().trim(),
+                phoneField.getValue().trim(),
+                messageField.getValue().trim()));
+        grid.setItems(messages.findAll());
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        // Clearing the fields fires the value change listeners, so disable Send after them.
+        sendButton.setEnabled(false);
+
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        clearErrors();
+
+        var name = nameField.getValue().trim();
+        var email = emailField.getValue().trim();
+        var phone = phoneField.getValue().trim();
+        var message = messageField.getValue().trim();
+
+        if (name.isEmpty()) {
+            markInvalid(nameField, "Name is required");
+        }
+        if (!email.isEmpty() && !EMAIL_ADDRESS.matcher(email).matches()) {
+            markInvalid(emailField, "Enter a valid e-mail address");
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            markInvalid(emailField, "Give an e-mail address or a phone number");
+        }
+        if (message.isEmpty()) {
+            markInvalid(messageField, "Message is required");
+        } else if (message.codePointCount(0, message.length()) > MAX_MESSAGE_LENGTH) {
+            markInvalid(messageField, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+        }
+
+        return !(nameField.isInvalid() || emailField.isInvalid() || messageField.isInvalid());
+    }
+
+    private void clearErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private static void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasTypedText()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasTypedText() {
+        return !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+    }
+
+    private void discardAndLeave() {
+        leaveDialog.close();
+        pendingNavigation.proceed();
+    }
+}
