+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.assertj.core.api.Assertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.List;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.AfterEach;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private ContactMessageService messages;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @BeforeEach
+    void startWithNoMessages() {
+        // The base class has already loaded the page, so clear the store and load the view again
+        messages.clear();
+        page.reload();
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    @AfterEach
+    void clearMessagesAfterTest() {
+        messages.clear();
+    }
+
+    @Test
+    void pageShowsHeadingAboutLinkAndAnEmptyEnabledForm() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(aboutLink()).isVisible();
+        assertThat(name().getInputLocator()).hasValue("");
+        assertThat(email().getInputLocator()).hasValue("");
+        assertThat(phone().getInputLocator()).hasValue("");
+        assertThat(message().getInputLocator()).hasValue("");
+        send().assertEnabled();
+    }
+
+    @Test
+    void emptySubmitMarksTheRequiredFieldsAndSendsNothing() {
+        send().click();
+
+        name().assertErrorMessage("Name is required");
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertErrorMessage("Message is required");
+        phone().assertValid();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(messages.findAll()).isEmpty();
+    }
+
+    @Test
+    void malformedEmailIsReportedInTheBrowser() {
+        name().setValue("Ann");
+        email().setValue("not-an-address");
+        message().setValue("Hello");
+
+        send().click();
+
+        email().assertErrorMessage("Enter a valid e-mail address");
+        assertThat(messages.findAll()).isEmpty();
+    }
+
+    @Test
+    void sendingShowsNotificationAddsTheRowAndResetsTheForm() {
+        fillIn("Ann", "ann@example.com", "+358 40 123 4567", "Hello there");
+
+        send().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        waitForRowContaining(0, "Ann");
+        waitForRowContaining(0, "Hello there");
+        assertThat(name().getInputLocator()).hasValue("");
+        assertThat(message().getInputLocator()).hasValue("");
+        send().assertDisabled();
+
+        name().setValue("Bo");
+        send().assertEnabled();
+    }
+
+    @Test
+    void newestMessageIsTheFirstRow() {
+        fillIn("First", "", "+358 1", "one");
+        send().click();
+        waitForRowContaining(0, "First");
+        fillIn("Second", "", "+358 2", "two");
+        send().click();
+
+        waitForRowContaining(0, "Second");
+        waitForRowContaining(1, "First");
+    }
+
+    @Test
+    void enterInTheMessageFieldSends() {
+        fillIn("Ann", "ann@example.com", "", "Hello");
+
+        message().getInputLocator().press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(messages.findAll()).hasSize(1);
+        assertThat(name().getInputLocator()).hasValue("");
+    }
+
+    @Test
+    void shiftEnterInTheMessageFieldStartsANewLine() {
+        fillIn("Ann", "ann@example.com", "", "first line");
+
+        message().getInputLocator().press("Shift+Enter");
+
+        assertThat(message().getInputLocator()).hasValue("first line\n");
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(messages.findAll()).isEmpty();
+    }
+
+    @Test
+    void enterOnTheAboutLinkFollowsTheLink() {
+        aboutLink().press("Enter");
+
+        page.waitForURL("**/about");
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void enterOnTheAboutLinkWithTypedTextAsksFirstAndDoesNotSend() {
+        fillIn("Ann", "ann@example.com", "", "Hello");
+
+        aboutLink().press("Enter");
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByText("Message sent")).not().isVisible();
+        assertThat(messages.findAll()).isEmpty();
+    }
+
+    @Test
+    void aboutLinkChangesTheViewWithoutAReload() {
+        page.evaluate("window.marker = 'kept'");
+
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertEquals("kept", page.evaluate("window.marker"));
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysPut() {
+        name().setValue("Ann");
+
+        aboutLink().click();
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(name().getInputLocator()).hasValue("Ann");
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        message().setValue("Hello");
+
+        aboutLink().click();
+        ButtonElement.getByText(page, "Discard").click();
+
+        page.waitForURL("**/about");
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void leavingWithAnEmptyFormIsNotInterrupted() {
+        aboutLink().click();
+
+        page.waitForURL("**/about");
+        assertThat(page.locator("h1")).hasText("About");
+        DialogElement.getByHeaderText(page, "Discard your message?").assertClosed();
+    }
+
+    @Test
+    void sentMessagesAreListedAgainWhenTheViewIsReopened() {
+        fillIn("Ann", "ann@example.com", "", "Hello");
+        send().click();
+        assertThat(page.getByText("Message sent")).isVisible();
+
+        aboutLink().click();
+        page.waitForURL("**/about");
+        // Let the About view render before going back, or the back navigation can race it
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+
+        page.waitForURL("**/contact");
+        waitForRowContaining(0, "Ann");
+    }
+
+    private void fillIn(String nameText, String emailText, String phoneText, String messageText) {
+        name().setValue(nameText);
+        email().setValue(emailText);
+        phone().setValue(phoneText);
+        message().setValue(messageText);
+    }
+
+    /**
+     * Waits until the data row at this index shows the text. Row 1 of the grid is the header, so
+     * data row N has aria-rowindex N+2. The cells are slotted light-DOM content, so the text is read
+     * from the elements assigned to each cell's slot.
+     */
+    private void waitForRowContaining(int index, String text) {
+        page.waitForFunction("""
+                ([index, text]) => {
+                  const grid = document.querySelector('vaadin-grid');
+                  const row = grid && grid.shadowRoot.querySelector(`tr[aria-rowindex="${index + 2}"]`);
+                  if (!row) return false;
+                  const cells = [...row.querySelectorAll('slot')]
+                      .map(slot => slot.assignedElements().map(el => el.textContent).join(''));
+                  return cells.join(' | ').includes(text);
+                }
+                """, List.of(index, text), new Page.WaitForFunctionOptions().setPollingInterval(100));
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+}
